      SUBROUTINE DFOCU3CC     DERIVATIVE OF THIRD-ORDER TRANSFER MATRIX ELEMENTS WITH RESPECT C     TO MAGNETIC FIELD OR GRADIENTCC ----------------------------------------------------------------------      INCLUDE 'ELM0B.CIN'      INCLUDE 'ELM5A.CIN'      INCLUDE 'ELM5B.CIN'      INCLUDE 'ELM5C.CIN'      INCLUDE 'R.CIN'      INCLUDE 'U.CIN'CC     LOCAL VARIABLESC      INTEGER        JO, KLM      REAL           DCS, DCSO, DSN, DSNOC-----------------------------------------------------------------------C      J = JQUAD      JO = 4 - J      CS = R(J,J)      SN = R(J,J+1)      DCS = RV(J,J)      DSN = RV(J,J+1)      DCSO = RV(JO,JO)      DSNO = RV(JO,JO+1)C      IF (J .EQ. 1) KLM = 1      IF (J .EQ. 3) KLM = 10      UV(J,KLM) = 4.0*KVK*U(J,KLM)/KQ2     1          + KQ2**2*(13.*DCS*SN**2 + 26.*CS*SN*DSN - 9.*L*DSN)/48.      UV(J+1,KLM) = 4.0*KVK*U(J+1,KLM)/KQ2     1            - KQ2**2*(7.*DSN + 30.*KVK*SN**3 + 45.*KQ2*SN**2*DSN     2            + 9.*L*DCS)/48.      IF (J .EQ. 1) KLM = 2      IF (J .EQ. 3) KLM = 16      UV(J,KLM) = 2.0*KVK*U(J,KLM)/KQ2     1          + KQ2*(- 22.*DSN + 52.*KVK*SN**3 + 78.*KQ2*SN**2*DSN     2          + 6.*L*DCS)/32.      UV(J+1,KLM) = 4.0*KVK*U(J+1,KLM)/KQ2     1            + 3.*KQ2**2*(5.*DCS*SN**2 + 10.*CS*SN*DSN     2            - L*DSN)/16.      IF (J .EQ. 1) KLM = 3      IF (J .EQ. 3) KLM = 19      UV(J,KLM) = 2.0*KVK*U(J,KLM)/KQ2     1          - KQ2*(13.*DCS*SN**2 + 26.*CS*SN*DSN + 3.*L*DSN)/16.      UV(J+1,KLM) = 2.0*KVK*U(J+1,KLM)/KQ2     1            + KQ2*(- 26.*DSN + 60.*KVK*SN**3 + 90.*KQ2*SN**2*DSN     2            - 6.*L*DCS)/32.      IF (J .EQ. 1) KLM = 4      IF (J .EQ. 3) KLM = 20      UV(J,KLM) = (-9.*DSN - 26.*KVK*SN**3     1          - 39.*KQ2*SN**2*DSN + 9.*L*DCS)/48.      UV(J+1,KLM) = 2.0*KVK*U(J+1,KLM)/KQ2     1            - KQ2*(5.*DCS*SN**2 + 10.*CS*SN*DSN + 3.*L*DSN)/16.      IF (J .EQ. 1) KLM = 8      IF (J .EQ. 3) KLM = 5      UV(J,KLM) = 4.0*KVK*U(J,KLM)/KQ2     1          + KQ2**2*(- 3.*DCS*SNO**2 - 6.*CS*SNO*DSNO + 2.*L*DSN     2          - 3.*DSN*SNO*CSO - 3.*SN*DSNO*CSO - 3.*SN*SNO*DCSO)/16.      UV(J+1,KLM) = 4.0*KVK*U(J+1,KLM)/KQ2     1            + KQ2**2*(2.*L*DCS - 9.*DCS*CSO*SNO - 9.*CS*DCSO*SNO     2            - 9.*CS*CSO*DSNO - 9.*DSN - 22.*KVK*SN*SNO**2     3            - 11.*KQ2*DSN*SNO**2 - 22.*KQ2*SN*SNO*DSNO)/16.      IF (J .EQ. 1) KLM = 14      IF (J .EQ. 3) KLM = 6      UV(J,KLM) = 2.0*KVK*U(J,KLM)/KQ2     1          + 3.*KQ2*(- DCS*CSO*SNO - CS*DCSO*SNO - CS*CSO*DSNO     2          + DSN - 2.0*KVK*SN*SNO**2 - KQ2*DSN*SNO**2     3          - 2.0*KQ2*SN*SNO*DSNO)/8.      UV(J+1,KLM) = 4.0*KVK*U(J+1,KLM)/KQ2     1            + KQ2**2*(- 9.*DCS*SNO**2 - 18.*CS*SNO*DSNO     2            - 11.*DSN*SNO*CSO - 11.*SN*DSNO*CSO     3            - 11.*SN*SNO*DCSO)/8.      IF (J .EQ. 1) KLM = 17      IF (J .EQ. 3) KLM = 7      UV(J,KLM) = 2.0*KVK*U(J,KLM)/KQ2     1          - KQ2*(3.*DCS*SNO**2 + 6.*CS*SNO*DSNO + 2.*L*DSN     2          + 3.*DSN*CSO*SNO + 3.*SN*DCSO*SNO + 3.*SN*CSO*DSNO)/16.      UV(J+1,KLM) = 2.0*KVK*U(J+1,KLM)/KQ2     1            - KQ2*(2.*L*DCS + 9.*DCS*CSO*SNO + 9.*CS*DCSO*SNO     2            + 9.*CS*CSO*DSNO + 22.*KVK*SN*SNO**2     3            + 11.*KQ2*DSN*SNO**2 + 22.*KQ2*SN*SNO*DSNO     4            + 5.*DSN)/16      IF (J .EQ. 1) KLM = 9      IF (J .EQ. 3) KLM = 11      UV(J,KLM) = 2.0*KVK*U(J,KLM)/KQ2     1          + KQ2*(3.*DCS*CSO*SNO + 3.*CS*DCSO*SNO + 3.*CS*CSO*DSNO     2          - 2.*L*DCS - 3.*DSN*CSO**2 - 6.*SN*CSO*DCSO     3          - 6.*DSN)/16.      UV(J+1,KLM) = 4.0*KVK*U(J+1,KLM)/KQ2     1            + KQ2**2*(11.*DCS*SNO**2 + 22.*CS*SNO*DSNO + 2.*L*DSN     2            - 9.*DSN*CSO*SNO - 9.*SN*DCSO*SNO     3            - 9.*SN*CSO*DSNO)/16      IF (J .EQ. 1) KLM = 15      IF (J .EQ. 3) KLM = 12      UV(J,KLM) = 2.0*KVK*U(J,KLM)/KQ2     1          + 3.*KQ2*(DCS*SNO**2 + 2.*CS*SNO*DSNO - DSN*CSO*SNO     2          - SN*DCSO*SNO - SN*CSO*DSNO)/8.      UV(J+1,KLM) = 2.0*KVK*U(J+1,KLM)/KQ2     1            + KQ2*(11.*DCS*CSO*SNO + 11.*CS*DCSO*SNO     2            + 11.*CS*CSO*DSNO - 3.*DSN - 18.*KVK*SN*SNO**2     3            - 9.*KQ2*DSN*SNO**2 - 18.*KQ2*SN*SNO*DSNO)/8.      IF (J .EQ. 1) KLM = 18      IF (J .EQ. 3) KLM = 13      UV(J,KLM) = (3.*DCS*CSO*SNO + 3.*CS*DCSO*SNO     1          + 3.*CS*CSO*DSNO + 2.*L*DCS - 3.*DSN*CSO**2     2          - 6.*SN*CSO*DCSO - 2.*DSN)/16.      UV(J+1,KLM) = 2.0*KVK*U(J+1,KLM)/KQ2     1            + KQ2*(11.*DCS*SNO**2 + 22.*CS*SNO*DSNO - 2.*L*DSN     2            - 9.*DSN*CSO*SNO - 9.*SN*DCSO*SNO     3            - 9.*SN*CSO*DSNO)/16      UV(J,50+J) = 2.0*KVK*U(J,50+J)/KQ2     1           - KQ2*(3.*L*DSN + L**2*DCS)/8.      UV(J,51+J) = ( - 2.0*KVK*L**2*SN - KQ2*L**2*DSN + L*DCS     1           - DSN)/8.      UV(J+1,50+J) = 2.0*KVK*U(J+1,50+J)/KQ2     1             + KQ2*(- 5.*L*DCS - 3.*DSN + 2.0*KVK*L**2*SN     2             + KQ2*L**2*DSN)/8.      UV(J+1,51+J) = 2.0*KVK*U(J+1,51+J)/KQ2     1             + KQ2*(- 3.*L*DSN - L**2*DCS)/8.      RETURN      END